            properties?: FilePropertyBag
        ) {
            this.parts = parts;
            this.name = name;
            this.size = parts.join('').length;
            this.type = 'txt';
            this.properties = properties;
            this.lastModified = 1234567890000; // Sat Feb 13 2009 23:31:30 GMT+0000.
